# /// script
# requires-python = ">=3.12"
#
# [tool.orcaslicer.plugin]
# id = "q2-spool-presets"
# name = "Q2 Spool Presets"
# description = "Adds a Q2 Box tab and keeps one filament preset per Spoolman spool, generated by q2-offload."
# author = "q2-offload"
# version = "0.3.0"
# ///
"""A "Q2 Box" tab showing the spool in each gate, and the presets q2-offload generates from
Spoolman installed as a local bundle.

Each preset has its own filament_id, so "Sync filaments" selects the spool in each Box slot.
It refreshes on its own when the printer comes online and when the tab opens; all the logic is
on the host (scripts/orca-spool-presets.py). A page plugin stays loaded, unlike a script, and an
error here must never escape: OrcaSlicer disables a plugin that fails.
"""
import json
import os
import pathlib
import time
import urllib.parse
import urllib.request
import webbrowser

import orca

BUNDLE_ID = "q2-spool-presets"
STATE_FILE = ".q2-spool-presets-state.json"
TIMEOUT_SECONDS = 4


def spools_url(print_host):
    host = str(print_host or "").strip().rstrip("/")
    if not host:
        raise ValueError("the printer preset has no host address")
    if "://" not in host:
        host = "http://" + host
    parts = urllib.parse.urlsplit(host)
    return "%s://%s/q2-spools/" % (parts.scheme, parts.netloc)


def fetch(url):
    with urllib.request.urlopen(url, timeout=TIMEOUT_SECONDS) as response:
        return response.read()


def data_dir():
    parts = pathlib.Path(os.path.abspath(__file__)).parts
    return pathlib.Path(*parts[: parts.index("orca_plugins")])


def user_folder(bundle):
    """The account folder, from where an existing user preset is stored."""
    for collection in (bundle.filaments, bundle.prints, bundle.printers):
        for index in range(collection.size()):
            parts = pathlib.Path(collection.preset(index).file or "").parts
            if "user" in parts and parts.index("user") + 1 < len(parts):
                return parts[parts.index("user") + 1]
    return "default"


def sync_files(target, index):
    """Make target/filament match the index. Returns True when something changed."""
    state_path = target / STATE_FILE
    previous = json.loads(state_path.read_text()) if state_path.exists() else {}
    if previous.get("hash") == index["hash"]:
        return False
    folder = target / "filament"
    folder.mkdir(parents=True, exist_ok=True)
    for name, content in index["files"].items():
        (folder / name).write_text(content, encoding="utf-8")
    for old in folder.glob("*.json"):
        if old.name not in index["files"]:
            old.unlink()
    (target / "bundle_metadata.json").write_text(
        json.dumps({"id": BUNDLE_ID, "name": "Q2 Spool Presets", "version": "0.1.0"}))
    return True


def sync(bundle):
    index = json.loads(fetch(spools_url(bundle.full_config_value("print_host")) + "index.json"))
    target = data_dir() / "user" / user_folder(bundle) / "_local" / BUNDLE_ID
    changed = sync_files(target, index)
    if changed:
        orca.host.preset.bundles.reload_local(BUNDLE_ID)
        # Only after Orca accepted the bundle, so a refused one is tried again
        (target / STATE_FILE).write_text(json.dumps({"hash": index["hash"]}))
    return index, changed


PAGE = """
<style>
  :root { --q2-fg: var(--orca-fg, #e8e8e8); --q2-bg: var(--orca-bg, #1f1f23); --q2-muted: var(--orca-muted, #9a9aa2);
          --q2-border: var(--orca-border, #3a3a40); --q2-accent: var(--orca-accent, #00ae42);
          --q2-accent-fg: var(--orca-accent-fg, #fff); }
  * { box-sizing: border-box; }
  body { margin: 0; padding: 24px; font: 13px/1.45 var(--orca-font, -apple-system, system-ui, sans-serif);
         color: var(--q2-fg); background: var(--q2-bg); }
  main { max-width: 860px; margin: 0 auto; }
  header { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
  h1 { margin: 0; font-size: 20px; font-weight: 600; }
  .chips { display: flex; gap: 6px; flex-wrap: wrap; flex: 1; }
  .chip { padding: 2px 10px; border: 1px solid var(--q2-border); border-radius: 999px; color: var(--q2-muted);
          font-variant-numeric: tabular-nums; }
  .chip.on { color: var(--q2-accent); border-color: var(--q2-accent); }
  button { font: inherit; color: var(--q2-fg); background: transparent; border: 1px solid var(--q2-border);
           border-radius: 6px; padding: 6px 14px; cursor: pointer; }
  button:hover { border-color: var(--q2-accent); }
  button.primary { background: var(--q2-accent); border-color: var(--q2-accent); color: var(--q2-accent-fg); }
  button:disabled { opacity: .6; cursor: progress; }
  .box { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; padding: 14px;
         border: 1px solid var(--q2-border); border-radius: 14px;
         background: linear-gradient(180deg, rgba(128,128,128,.14), rgba(128,128,128,.04)); }
  .bay { position: relative; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 6px 10px;
         color: inherit; text-align: center; background: rgba(0,0,0,.14); border: 2px solid transparent; border-radius: 10px; }
  .bay:hover { border-color: var(--q2-border); }
  .bay.selected { border-color: var(--q2-accent); }
  .bay .slot { align-self: flex-start; color: var(--q2-muted); font-size: 11px; font-weight: 600; }
  .bay svg { width: 100%; max-width: 132px; height: auto; display: block; }
  .bay .name { font-weight: 600; min-height: 38px; overflow-wrap: anywhere; }
  .bay .weight { color: var(--q2-muted); font-variant-numeric: tabular-nums; }
  .tag { position: absolute; top: 8px; right: 8px; padding: 0 7px; border-radius: 999px; font-size: 11px;
         background: var(--q2-accent); color: var(--q2-accent-fg); }
  .details { margin-top: 14px; padding: 16px; border: 1px solid var(--q2-border); border-radius: 10px; }
  .details h2 { margin: 0 0 10px; font-size: 15px; font-weight: 600; }
  dl { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px 16px; margin: 0 0 14px; }
  dt { color: var(--q2-muted); font-size: 11px; }
  dd { margin: 0; font-variant-numeric: tabular-nums; }
  footer { margin-top: 12px; color: var(--q2-muted); }
  footer.error { color: #e5484d; }
  @media (max-width: 560px) { .box { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
</style>
<main>
  <header>
    <h1>Q2 Box</h1>
    <div class="chips" id="chips"></div>
    <button type="button" id="refresh" class="primary">Update</button>
  </header>
  <div class="box" id="box"></div>
  <section class="details" id="details"></section>
  <footer id="status">Reading the printer...</footer>
</main>
<script>
const $ = id => document.getElementById(id);
const POLL_MS = 30000;
let state = { gates: [], box: {} };
let selected = null;

function element(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

// Remaining filament is the thickness of the coloured ring on the spool
function spoolImage(gate) {
  const svgNs = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(svgNs, 'svg');
  svg.setAttribute('viewBox', '0 0 120 120');
  svg.setAttribute('aria-hidden', 'true');
  const circle = (radius, fill, stroke, width, dash) => {
    const shape = document.createElementNS(svgNs, 'circle');
    shape.setAttribute('cx', 60); shape.setAttribute('cy', 60); shape.setAttribute('r', radius);
    shape.setAttribute('fill', fill);
    if (stroke) { shape.setAttribute('stroke', stroke); shape.setAttribute('stroke-width', width); }
    if (dash) shape.setAttribute('stroke-dasharray', dash);
    svg.append(shape);
  };
  if (gate.empty) {
    circle(52, 'none', 'rgba(128,128,128,.55)', 2, '5 5');
    circle(18, 'none', 'rgba(128,128,128,.55)', 2, '5 5');
    return svg;
  }
  const hub = 20, outer = 52;
  const percent = gate.percent === undefined || gate.percent === null ? 100 : Math.max(4, Math.min(100, gate.percent));
  const radius = hub + (outer - hub) * percent / 100;
  circle(56, 'rgba(128,128,128,.28)', 'rgba(128,128,128,.6)', 1.5);
  circle(radius, '#' + gate.color, 'rgba(255,255,255,.28)', 1);
  for (let ring = hub + 6; ring < radius - 1; ring += 6) circle(ring, 'none', 'rgba(0,0,0,.12)', 1);
  circle(hub, '#2a2a2e', 'rgba(255,255,255,.25)', 1.5);
  circle(7, '#111114', 'rgba(255,255,255,.2)', 1);
  return svg;
}

function title(gate) {
  if (gate.empty) return 'Empty';
  return gate.spool_id ? gate.vendor + ' ' + gate.filament : (gate.material || 'Unknown') + ' (no spool)';
}

function drawBox() {
  $('box').replaceChildren(...state.gates.map(gate => {
    const bay = element('button', 'bay' + (selected === gate.slot ? ' selected' : ''));
    bay.type = 'button';
    bay.setAttribute('aria-pressed', selected === gate.slot);
    bay.onclick = () => { selected = gate.slot; drawBox(); drawDetails(); };
    bay.append(element('span', 'slot', 'SLOT ' + gate.slot));
    if (state.box.loaded_slot === gate.slot) bay.append(element('span', 'tag', 'Loaded'));
    bay.append(spoolImage(gate), element('span', 'name', title(gate)));
    const weight = gate.remaining_g === undefined || gate.remaining_g === null ? '' :
      gate.remaining_g + ' g' + (gate.percent === null ? '' : ' · ' + gate.percent + '%');
    bay.append(element('span', 'weight', gate.empty ? ' ' : weight || gate.material));
    return bay;
  }));
}

function drawDetails() {
  const gate = state.gates.find(item => item.slot === selected);
  const panel = $('details');
  panel.replaceChildren();
  panel.hidden = !gate;
  if (!gate) return;
  panel.append(element('h2', '', 'Slot ' + gate.slot + ': ' + title(gate)));
  if (!gate.spool_id) {
    panel.append(element('div', '', gate.empty ? 'No filament in this slot.' : 'This slot has no Spoolman spool. Scan its NFC tag or assign one in Spoolman.'));
    return;
  }
  const rows = [['Spool', '#' + gate.spool_id], ['Material', gate.material], ['Remaining', gate.remaining_g === null ? '-' : gate.remaining_g + ' g'],
    ['Nozzle', gate.nozzle ? gate.nozzle + ' °C' : '-'], ['Pressure advance', gate.pressure_advance || '-'], ['Last used', gate.last_used || '-']];
  const entries = element('dl');
  rows.forEach(([name, value]) => { const cell = element('div'); cell.append(element('dt', '', name), element('dd', '', value)); entries.append(cell); });
  const open = element('button', '', 'Open in Spoolman');
  open.type = 'button';
  open.onclick = () => orca.postMessage({ command: 'open_spool', spool_id: gate.spool_id });
  panel.append(entries, open);
}

function drawChips() {
  const box = state.box || {};
  const chips = [];
  if (box.temperature !== undefined && box.temperature !== null) chips.push([Math.round(box.temperature) + ' °C']);
  if (box.humidity !== undefined && box.humidity !== null) chips.push([Math.round(box.humidity) + '% RH']);
  if (box.drying) chips.push(['Drying', true]);
  if (state.presets !== undefined) chips.push([state.presets + ' spools in Spoolman']);
  $('chips').replaceChildren(...chips.map(([label, on]) => element('span', 'chip' + (on ? ' on' : ''), label)));
}

function refresh() {
  $('refresh').disabled = true;
  $('refresh').textContent = 'Updating...';
  orca.postMessage({ command: 'refresh' });
}

$('refresh').onclick = refresh;
orca.onMessage(message => {
  $('refresh').disabled = false;
  $('refresh').textContent = 'Update';
  state = message;
  if (!state.gates.some(gate => gate.slot === selected)) {
    selected = (state.gates.find(gate => gate.slot === (state.box || {}).loaded_slot) || state.gates[0] || {}).slot || null;
  }
  drawChips(); drawBox(); drawDetails();
  $('status').textContent = message.status || '';
  $('status').className = message.error ? 'error' : '';
});
refresh();
setInterval(() => { if (!document.hidden) orca.postMessage({ command: 'refresh' }); }, POLL_MS);
</script>
"""


class Q2BoxPage(orca.pages.PagesPluginCapabilityBase):
    def get_name(self):
        return "Q2 Box"

    def get_icon(self):
        return "topbar_store"

    def get_ui(self):
        return PAGE

    def refresh(self):
        """Never raises. Returns what the page shows."""
        try:
            index, changed = sync(orca.host.preset_bundle())
            now = time.strftime("%H:%M:%S")
            detail = "presets updated" if changed else "presets up to date"
            self.spoolman_port = index.get("spoolman")
            return {"gates": index.get("gates", []), "box": index.get("box", {}), "presets": len(index["files"]),
                    "status": "Checked at %s, %s." % (now, detail)}
        except Exception as error:
            return {"gates": [], "box": {}, "error": True, "status": "Printer not available: %s" % error}

    def open_spool(self, spool_id):
        host = spools_url(orca.host.preset_bundle().full_config_value("print_host")).split("/")[2].split(":")[0]
        webbrowser.open("http://%s:%s/spool/show/%d" % (host, self.spoolman_port or 7912, int(spool_id)))

    def on_message(self, message):
        command = message.get("command") if isinstance(message, dict) else None
        if command == "refresh":
            self.post_message(self.refresh())
        elif command == "open_spool":
            try:
                self.open_spool(message.get("spool_id"))
            except Exception as error:
                self.post_message({**self.refresh(), "error": True, "status": "Could not open Spoolman: %s" % error})

    def on_lifecycle_event(self, event, ctx):
        if event in (orca.LifecycleEvent.DeviceOnline, orca.LifecycleEvent.DeviceSelected):
            self.post_message(self.refresh())


@orca.plugin
class Q2SpoolPresetsPackage(orca.base):
    def register_capabilities(self):
        orca.register_capability(Q2BoxPage)
